entries[938] = { ["name"] = "Schlammverschmierte Tagebuchseiten", ["text"] = "Questgegenstand\nEinzigartig\n\"Obwohl die Seiten von Schlamm verschmiert sind, kann man einige Worte entziffern.\"\n<Zum Lesen rechtsklicken>" }
