entries[940] = { ["name"] = "Roben der Einsicht", ["text"] = "Wird beim Anlegen gebunden\nBrust Stoff\n165 Rüstung\n+25 Intelligenz\n+15 Willenskraft\nHaltbarkeit 165 / 165\nBenötigt Stufe 42\nBenutzen: Verringert die Kosten Eures nächsten Zaubers, der innerhalb von 10 Sek. gewirkt wird, um bis zu 500 Manapunkte. (15 Min Abklingzeit)\nVerkaufspreis:" }
