entries[1341] = { ["name"] = "Buch des Mondfeuers", ["text"] = "Klassen: Mönch , Druide\nBenötigt Stufe 4\nBenutzen: Lehrt 'Mondfeuer' (Rang 1).\nÜberzieht einen Gegner mit 1 Arkanschaden und im Verlauf von 14 Sek. zusätzlich 41 Arkanschaden. [ Finsternis : Eure kritischen Treffer mit 'Sternenfeuer' und 'Sternensog' gegen das Ziel verlängern die Dauer Eures Zaubers 'Mondfeuer' um 2 Sek ]\nVerkaufspreis:" }
